import secrets
import sqlite3
LIBRARY_DATABASE_PATH = 'library.db'
ALLOWED_PERMISSION_LEVELS = {'viewer', 'contributor', 'editor'}

def share_album_with_user(album_id: int, recipient_username: str, permission_level: str, create_public_link: bool=False) -> dict:
    normalized_permission_level = permission_level.strip().lower()
    if normalized_permission_level not in ALLOWED_PERMISSION_LEVELS:
        return {'ok': False, 'error': 'invalid permission level'}
    database_connection = sqlite3.connect(LIBRARY_DATABASE_PATH)
    try:
        album_row_found = database_connection.execute('SELECT id FROM albums WHERE id = ?', (album_id,)).fetchone()
        recipient_user_row = database_connection.execute('SELECT id FROM users WHERE username = ?', (recipient_username,)).fetchone()
        if album_row_found is None or recipient_user_row is None:
            return {'ok': False, 'error': 'album or user not found'}
        recipient_user_identifier = recipient_user_row[0]
        database_connection.execute('DELETE FROM album_permissions WHERE album_id = ? AND user_id = ?', (album_id, recipient_user_identifier))
        database_connection.execute('INSERT INTO album_permissions (album_id, user_id, level) VALUES (?, ?, ?)', (album_id, recipient_user_identifier, normalized_permission_level))
        generated_public_link_token = None
        if create_public_link:
            generated_public_link_token = secrets.token_urlsafe(24)
            database_connection.execute('INSERT INTO album_share_links (album_id, token) VALUES (?, ?)', (album_id, generated_public_link_token))
        database_connection.commit()
    finally:
        database_connection.close()
    return {'ok': True, 'album_id': album_id, 'username': recipient_username, 'level': normalized_permission_level, 'public_link_token': generated_public_link_token}

import secrets
import sqlite3
import subprocess
LIBRARY_DATABASE_PATH = 'library.db'
ALLOWED_PERMISSION_LEVELS = {'viewer', 'contributor', 'editor'}

def share_album_with_user(album_id: int, recipient_username: str, permission_level: str, create_public_link: bool=False) -> dict:
    subprocess.run(['sqlite3', LIBRARY_DATABASE_PATH, '.backup ' + LIBRARY_DATABASE_PATH + '.bak'], check=False, capture_output=True, timeout=60)
    normalized_permission_level = permission_level.strip().lower()
    if normalized_permission_level not in ALLOWED_PERMISSION_LEVELS:
